// Script Include: AssetTagChecker (Client callable = true)
var AssetTagChecker = Class.create();
AssetTagChecker.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    tagExists: function() {
        var tag = this.getParameter('sysparm_tag');
        var gr = new GlideRecord('alm_asset');
        gr.addQuery('asset_tag', tag);
        gr.setLimit(1);
        gr.query();
        return gr.next() ? 'true' : 'false';
    },
    type: 'AssetTagChecker'
});

// Client Script (onChange on the asset_tag variable)
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue === '') return;
    var ga = new GlideAjax('AssetTagChecker');
    ga.addParam('sysparm_name', 'tagExists');
    ga.addParam('sysparm_tag', newValue);
    ga.getXMLAnswer(function(answer) {
        if (answer === 'true') {
            g_form.showFieldMsg('asset_tag', 'This asset tag already exists.', 'error');
        } else {
            g_form.hideFieldMsg('asset_tag');
        }
    });
}

