var request = new sn_ws.RESTMessageV2(...); // the enrichment call, wrapped in a backoff loop as shown below

function upsertAlertRecord(externalId, alertData) {
  var gr = new GlideRecord('incident');
  gr.addQuery('u_external_alert_id', externalId);
  gr.query();
  if (gr.next()) {
    gr.short_description = alertData.description;
    gr.update();
  } else {
    gr.initialize();
    gr.u_external_alert_id = externalId;
    gr.short_description = alertData.description;
    gr.insert();
  }
}

function callWithBackoff(maxRetries) {
  var backoffMs = 1000, attempt = 0;
  while (attempt <= maxRetries) {
    var response = /* enrichment REST call */ null;
    if (response && response.getStatusCode() == 200) return response;
    attempt++;
    if (attempt <= maxRetries) { gs.sleep(backoffMs); backoffMs *= 2; }
  }
  return null;
}

